var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`INTERN_FENRIR_NULL_NULL`,text:{KOREA:`소대장님에게, 시윤 선배에게, 미나 선배에게…. 그리고 그리고 사장님에게도! 당당하게 펜릴 소대의 일원으로 인정 받을 때까지 절~대로 멈추지 않을 테니까요! 기대해 주세요, 에헷~`,JPN:`小隊長様、アキヤマ先輩、ミナ先輩……それから、社長まで！　堂々とフェンリル小隊の一員として認められるまで、ぜ～ったいに止まりませんから！　期待していてください、えへっ～`,ENG:`To the Commander, to Shiyoon, to Mina... and, and to Boss! I'm NEVER gonna stop until I'm accepted as a proud member of Fenrir Squad! You can bet on me, he he!`,TWN:`在小隊長、時雲前輩、米娜前輩，還有…還有老闆！認同我是芬里爾小隊的一員之前，我是絕～對不會停止成長的！敬請期待我的表現，嘿嘿～`},stage:{bg:`LIFETIME`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`INTERN_FENRIR_NULL_NULL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};